+/* boot_wait_ready predicate: fires when LCD row 0 has any non-space content.
+ * An LCD write proves the firmware completed its init sequence and is polling
+ * buttons — the correct point to begin injecting front-panel events. */
+static bool lcd_row0_ready(nava_sim_t *ctx, void *user) {
+    (void)user;
+    const char *line = nava_lcd_get_line(ctx->lcd, 0);
+    return line && line[0] != '\0' && line[0] != ' ';
+}
+
+uint64_t boot_wait_ready(nava_sim_t *ctx, uint64_t max_cycles) {
+    uint64_t consumed = nava_sim_run_until(ctx, max_cycles,
+                                            lcd_row0_ready, NULL);
+    if (!lcd_row0_ready(ctx, NULL)) {
+        printf("# boot_wait_ready: LCD row 0 still blank after %llu cycles "
+               "(firmware may not have reached run loop — check EEPROM seed "
+               "or increase BOOT_CYCLES)\n",
+               (unsigned long long)consumed);
+    } else {
+        const char *line = nava_lcd_get_line(ctx->lcd, 0);
+        printf("# boot_wait_ready: ready after %llu cycles; "
+               "LCD[0]=\"%.16s\"\n",
+               (unsigned long long)consumed, line ? line : "");
+    }
+    return consumed;
+}
